  OPTIONAL { ?obj rdfs:label ?label }
}

SELECT ?p ?cls ?obj WHERE {
  ?p ?pred ?obj .
  FILTER (STR(?p) LIKE "%Zone_F2_Z07%")
  FILTER (STR(?obj) LIKE "%TimeseriesId%" OR STRSTARTS(STR(?obj), "ts") || STR(?obj) LIKE "%ts%" ) 
}

SELECT ?p ?rel ?tsid WHERE {
  ?p a brick:Zone_Air_Temperature_Sensor .
  FILTER (STRSTARTS(STR(?p), "http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z07"))
  ?p ?rel ?tsid .
  FILTER(?rel != rdf:type)
}

